<script lang="ts">
 import {onMount} from 'svelte';import {api,type ProblemDetail,type User} from './api';import DOMPurify from 'dompurify';import {marked} from 'marked';
 export let problem:ProblemDetail;export let user:User;export let onerror:(e:string)=>void;
 let host:HTMLDivElement, language:'cpp'|'python'='cpp',editor:any,monaco:any,semantic='Starting editor…',busy=false,result:any=null,history:any[]=[],tab='results',alive=true,subscription:any,disconnect:(()=>void)|undefined;
 const key=()=>`practice:${user.id}:${problem.version}:${language}`;
 const statement=DOMPurify.sanitize(marked.parse(problem.problem.statement,{async:false}) as string);
 const visibleTests=()=>problem.problem.tests.filter((test:any)=>!test.hidden);
 function save(){if(editor)localStorage.setItem(key(),editor.getValue())}
 function display(value:unknown,missing='Not provided'){return value===undefined?missing:JSON.stringify(value)}
 function currentOutput(test:any){return test?test.output===null?'No output':display(test.output):'Not executed'}
 async function connect(){disconnect?.();semantic='Connecting semantic completion…';try{const lsp=await import('./semantic');disconnect=await lsp.connect(monaco,editor,language,(s:string)=>semantic=s)}catch{semantic='Basic completion · semantic service unavailable'}}
 async function change(){disconnect?.();const old=editor.getModel();const model=monaco.editor.createModel(localStorage.getItem(key())||problem.starters[language],language==='cpp'?'cpp':'python',monaco.Uri.parse(`file:///workspace/solution.${language==='cpp'?'cpp':'py'}`));editor.setModel(model);old?.dispose();await connect()}
 async function historyLoad(){history=await api(`/submissions?version=${problem.version}`)}
 onMount(()=>{alive=true;(async()=>{try{const setup=await import('./monaco');await setup.initialize();monaco=setup.monaco;editor=monaco.editor.create(host,{value:localStorage.getItem(key())||problem.starters[language],language:'cpp',theme:'vs-dark',automaticLayout:true,minimap:{enabled:false},fontSize:14,padding:{top:18},scrollBeyondLastLine:false,autoClosingBrackets:'always',autoClosingQuotes:'always',autoIndent:'full',insertSpaces:true,tabSize:4,bracketPairColorization:{enabled:true},formatOnType:false,formatOnPaste:false});subscription=editor.onDidChangeModelContent(save);await change();await historyLoad()}catch(e){onerror(String(e))}})();return()=>{alive=false;save();disconnect?.();subscription?.dispose();editor?.getModel()?.dispose();editor?.dispose()}});
 async function execute(mode:'run'|'submit'){busy=true;result=null;tab='results';try{save();const r=await api('/submissions','POST',{version:problem.version,language,source:editor.getValue(),mode},crypto.randomUUID());for(let count=0;alive&&count<4000;count++){const s=await api(`/submissions/${r.id}`);if(s.status==='completed'){result=s.result;break}await new Promise(resolve=>setTimeout(resolve,1000))}await historyLoad()}catch(e){onerror(String(e))}finally{busy=false}}
</script>

<div class="workspace"><section class="statement-pane"><h1>{problem.problem.title}</h1><div class="tags">{#each problem.problem.tags as tag}<span>{tag}</span>{/each}</div><article class="statement">{@html statement}</article><h3>Examples</h3>{#each visibleTests() as t,i}<div class="example"><b>Example {i+1}</b><pre>Arguments: {display(t.args)}<br/>Expected:  {display(t.expected)}</pre></div>{/each}<p class="muted small">{problem.problem.limits.time_ms} ms · {problem.problem.limits.memory_mib} MiB per test<br/>Standard libraries · Solution class method</p></section><section class="code-pane"><div class="editor-toolbar"><label class="sr-only" for="language">Language</label><select id="language" value={language} onchange={async(e)=>{save();language=e.currentTarget.value as 'cpp'|'python';await change()}} disabled={busy}><option value="cpp">C++20</option><option value="python">Python 3</option></select><span>solution.{language==='cpp'?'cpp':'py'}</span><div class="actions"><button onclick={()=>execute('run')} disabled={busy||!editor}>▷ Run</button><button class="primary" onclick={()=>execute('submit')} disabled={busy||!editor}>{busy?'Judging…':'Submit →'}</button></div></div><div class="monaco-host" bind:this={host}></div><div class="semantic" role="status">● {semantic}<button onclick={connect}>Reconnect</button></div><div class="results"><div class="toolbar"><button class:chosen={tab==='results'} onclick={()=>tab='results'}>Results</button><button class:chosen={tab==='history'} onclick={()=>{tab='history';historyLoad()}}>History</button></div>{#if tab==='history'}{#each history as h}<button class="history" onclick={()=>{result=h.result;tab='results'}}>{h.language} · {h.mode}<span>{h.result?.verdict||h.status}</span><small>{new Date(h.created_at).toLocaleString()}</small></button>{:else}<p class="muted">No submissions yet.</p>{/each}{:else if busy}<p role="status">Your solution is queued or running…</p>{:else if result}<h3 class:notice={result.verdict==='accepted'}>{result.cases?.length && result.cases.every((c:any)=>c.verdict===null)?'Output only':result.verdict.replaceAll('_',' ')} {#if !result.cases?.length || result.cases.some((c:any)=>c.verdict!==null)}<small>{result.passed} / {result.total} passed</small>{/if}</h3>{#if result.diagnostic}<pre>{result.diagnostic}</pre>{/if}{#each visibleTests() as test,i}{@const current=result.cases?.[i]}<div class="case"><b>Visible case {i+1}: {current?.verdict?.replaceAll('_',' ')||'Output only'}</b><div class="comparison-cards"><div class="comparison-card"><span>Input</span><pre>{display(test.args)}</pre></div><div class="comparison-card"><span>Expected output</span><pre>{display(test.expected)}</pre></div><div class="comparison-card"><span>Current output</span><pre>{currentOutput(current)}</pre></div></div>{#if current?.log}<pre>{current.log}</pre>{/if}</div>{/each}<p class="muted small">Hidden cases contribute only to the verdict and pass count.</p>{:else}<p class="muted">Select Run or Submit to execute your solution.</p>{/if}</div></section></div>
